    "background:var(--rb-vino-sf);border:0;border-radius:99px;padding:8px 12px}",
    "#rh-drawer nav{overflow-y:auto}",

    /* bloque editorial ancho */
    ".rh-ed{position:relative;min-height:440px;display:flex;align-items:flex-end;border-radius:0;overflow:hidden}",
    ".rh-ed .rh-img{position:absolute;inset:0;height:100%}",
    ".rh-ed .rh-img:before{font-size:70px}",
    ".rh-ed .ed-tx{position:relative;z-index:4;width:100%;max-width:1180px;margin:0 auto;padding:40px 18px;color:#fff}",
    ".rh-ed:after{content:'';position:absolute;inset:0;z-index:3;background:linear-gradient(180deg,rgba(110,49,60,.05) 30%,rgba(110,49,60,.78) 100%)}",
    ".rh-ed h2{font-family:var(--rb-display);font-weight:600;font-size:clamp(27px,6.4vw,44px);line-height:1.05;margin:0;color:#fff}",
    ".rh-ed h2 em{font-style:italic;color:#fff}",
    ".rh-ed p{font-size:15px;line-height:1.7;margin:14px 0 22px;max-width:520px;color:#fff}",
