    ".rh-ed .rh-cta{background:var(--rb-hueso);color:var(--rb-vino)}",
    "@media(min-width:900px){.rh-ed{min-height:520px}.rh-ed .ed-tx{padding:56px 18px}}",

    /* comparador tipo tabla */
    ".rh-cp{overflow-x:auto;-webkit-overflow-scrolling:touch;padding-bottom:10px;scrollbar-width:none}",
    ".rh-cp::-webkit-scrollbar{display:none}",
    ".rh-cp table{border-collapse:separate;border-spacing:0;min-width:720px;width:100%;background:#fff;",
    "border:1px solid var(--rb-line);border-radius:20px;overflow:hidden}",
    ".rh-cp th,.rh-cp td{padding:14px 16px;text-align:left;vertical-align:top;font-size:13px;line-height:1.5;",
    "border-bottom:1px solid var(--rb-line)}",
    ".rh-cp thead th{background:var(--rb-hueso);vertical-align:bottom}",
    ".rh-cp thead th .cp-n{display:block;font-family:var(--rb-display);font-size:17px;font-weight:600;color:var(--rb-vino);line-height:1.15;margin:10px 0 4px}",
    ".rh-cp thead th .cp-p{display:block;font-size:15px;font-weight:800;color:var(--rb-tinta)}",
    ".rh-cp thead th .cp-b{display:inline-block;font-size:9px;font-weight:800;letter-spacing:.14em;text-transform:uppercase;",
