    ".rh-cp thead th .rh-img{aspect-ratio:1/1;border-radius:12px}",
    ".rh-cp tbody th{font-size:10.5px;font-weight:800;letter-spacing:.14em;text-transform:uppercase;color:var(--rb-muted);",
    "background:var(--rb-hueso);width:170px}",
    ".rh-cp td{font-weight:600;color:var(--rb-tinta)}",
