    "@media(min-width:800px){.rh-help{grid-template-columns:repeat(3,1fr);gap:18px}}",

    /* pagos y envios del footer */
    "#rh-foot .ft-pay{max-width:1180px;margin:30px auto 0;display:grid;grid-template-columns:1fr;gap:16px}",
