  function limpiaTxt(s) { return String(s || "").replace(/\s+/g, " ").trim(); }
  function plano(s) {
    return limpiaTxt(s).toLowerCase().normalize ? limpiaTxt(s).toLowerCase().normalize("NFD").replace(/[\u0300-\u036f]/g, "") : limpiaTxt(s).toLowerCase();
  }
  function numPrecio(t) {
    t = String(t || "").replace(/[^\d.,]/g, "");
    if (!t) return 0;
    t = t.replace(/\./g, "").replace(",", ".");
    var v = parseFloat(t); return isNaN(v) ? 0 : v;
  }
  /* Foto del producto en alta calidad. Tiendanube muestra primero una
     miniatura borrosa y guarda las versiones buenas en srcset /
     data-srcset. Se juntan todas las versiones de la MISMA foto y se usa
     la más grande; el navegador elige la justa para cada pantalla. Si
     el tema solo trae una chica, se pide la de 640 px (con respaldo). */
  var TN_TAM = /-(\d+)-(\d+)\.(webp|jpe?g|png)(\?.*)?$/i;
  function baseFoto(u) { return u.replace(TN_TAM, ""); }
  function fotoDe(b) {
    var cand = [], vistos = {}, base0 = "";
    function add(u, w) {
      u = String(u || "").trim();
      if (!u || /placeholder|data:image|empty-placeholder/i.test(u)) return;
      if (u.indexOf("//") === 0) u = "https:" + u;
      if (!base0) base0 = baseFoto(u);
      if (baseFoto(u) !== base0 || vistos[u]) return;
      vistos[u] = 1;
      if (!w) { var m = TN_TAM.exec(u); w = m ? parseInt(m[1], 10) : 0; }
      cand.push({ u: u, w: w || 0 });
    }
    Array.prototype.slice.call(b.querySelectorAll("img")).forEach(function (im) {
      if (/secondary|hover/i.test(im.className || "") && base0) return;
      ["data-srcset", "srcset"].forEach(function (a) {
        String(im.getAttribute(a) || "").split(",").forEach(function (p) {
          var t = p.trim().split(/\s+/);
          if (t[0]) add(t[0], parseInt(t[1], 10) || 0);
        });
      });
      ["data-src", "src"].forEach(function (a) { add(im.getAttribute(a)); });
    });
    if (!cand.length) return { src: "", set: "", fb: "" };
    cand.sort(function (a, c) { return a.w - c.w; });
    var top = cand[cand.length - 1], src = top.u, fb = "";
    var set = cand.filter(function (c) { return c.w >= 240; }).map(function (c) { return c.u + " " + c.w + "w"; });
    if (top.w && top.w < 640 && TN_TAM.test(src)) {
      fb = src;
      src = src.replace(TN_TAM, "-640-0.$3$4");
      set.push(src + " 640w");
    }
    return { src: src, set: set.join(", "), fb: fb };
  }
  /* Fotos de Cloudinary: formato y calidad automáticos; con "ar" se
     recortan a esa proporción (centrando lo importante). */
  function cldFoto(u, ar, ancho) {
    var m = /^(https?:\/\/res\.cloudinary\.com\/[^\/]+\/image\/upload\/)(v\d+\/.+)$/.exec(u || "");
    if (!m) return u;
    return m[1] + "f_auto,q_auto" + (ar ? ",c_fill,g_auto,ar_" + ar : "") + (ancho ? ",w_" + ancho : "") + "/" + m[2];
  }
  function leerProductos() {
    if (!CFG.leerProductosDelTema || PREVIEW) return [];
    var cajas = document.querySelectorAll(".js-item-product, .js-product-table-item, [class*='item-product']");
    if (cajas.length < 3) cajas = document.querySelectorAll("[data-store^='product-item'], .js-product-container, .item");
    var out = [], vistos = {};
    Array.prototype.slice.call(cajas).forEach(function (b) {
      var a = b.querySelector("a[href*='/productos/']");
      if (!a) return;
      var url = a.getAttribute("href") || "";
      if (!url || /\/productos\/?(\?|$)/.test(url)) return;
      var clave = url.split("?")[0];
      if (vistos[clave]) return;

      var nom = b.querySelector(".js-item-name, [class*='item-name'], .item-title, h2, h3");
      nom = limpiaTxt(nom ? nom.textContent : (a.getAttribute("title") || ""));
      var img = b.querySelector("img"), fo = fotoDe(b);
      if (!nom && img) nom = limpiaTxt(img.getAttribute("alt"));
      if (!nom) return;

      var p = b.querySelector(".js-price-display, [class*='price-display']:not([class*='compare'])");
      var pa = b.querySelector(".js-compare-price-display, [class*='compare-price']");
      var precio = limpiaTxt(p ? p.textContent : "");
      var ant = limpiaTxt(pa ? pa.textContent : "");
      if (!precio) {
        var m = limpiaTxt(b.textContent).match(/\$\s?[\d.]+(,\d{2})?/g);
        if (m && m.length) precio = m[m.length - 1];
      }
      if (numPrecio(precio) <= 0) return;
      if (numPrecio(ant) <= numPrecio(precio)) ant = "";

      var of = b.querySelector("[class*='offer'], [class*='discount']");
      var badge = of ? limpiaTxt(of.textContent) : "";
      if (!/%/.test(badge) || /^0\s?%/.test(badge)) badge = "";

      vistos[clave] = 1;
      out.push({ nombre: nom, precio: precio, anterior: ant, badge: badge, url: url, img: fo.src, imgSet: fo.set, imgFb: fo.fb });
    });
    return out;
  }
  function filtrar(lista, palabras, max) {
    var r = lista;
    if (palabras && palabras.length) {
      var ps = palabras.map(plano);
      r = lista.filter(function (x) {
        var n = plano(x.nombre);
        for (var i = 0; i < ps.length; i++) if (n.indexOf(ps[i]) !== -1) return true;
        return false;
      });
    }
    return r.slice(0, max || 10);
  }

  /* ---- 7b. Newsletter de Tiendanube ------------------------- */
  /* Suma el mail a la lista de newsletter de la tienda. Usa el
     formulario de newsletter del propio tema (queda escondido en la
     página) para mandar los mismos datos que manda Tiendanube; si no
     lo encuentra, arma el pedido estándar de la plataforma. */
  function suscribir(mail) {
    try {
      var tf = document.querySelector("[data-store='newsletter-form'], form.js-newsletter, form[class*='newsletter']");
      if (tf && tf.tagName !== "FORM") tf = tf.querySelector("form") || (tf.closest ? tf.closest("form") : null);
      if (!tf) {
        var tp = document.querySelector("form input[name='type'][value='newsletter']");
        tf = tp ? tp.form : null;
      }
      var fd, url = location.pathname || "/";
      if (tf) {
        fd = new FormData(tf);
        var em = tf.querySelector("input[type='email'], input[name='email']");
        fd.set(em && em.name ? em.name : "email", mail);
        var sb = tf.querySelector("[type='submit'][name]");
        if (sb) fd.set(sb.name, sb.value || "");
        var ac = tf.getAttribute("action") || "";
        if (ac && !/winnie-pooh/i.test(ac)) url = ac;
      } else {
        fd = new FormData();
        fd.set("email", mail);
        fd.set("name", "Sin nombre");
        fd.set("message", "Pedido de inscripción a newsletter");
        fd.set("type", "newsletter");
        fd.set("winnie-pooh", "");
      }
      var body = window.URLSearchParams ? new URLSearchParams(fd) : fd;
      if (window.fetch) fetch(url, { method: "POST", body: body, credentials: "same-origin" }).catch(function () {});
    } catch (er) {}
  }

  /* ---- 8. Armado --------------------------------------------- */
  var CAPA = document.createElement("div");
